{
  "contract": "DLAND",
  "closure": {
    "site_function": "retrieve_president",
    "site_call": ".call",
    "functions": [
      "retrieve_president",
      "retrieve_marketing",
      "retrieve_development",
      "retrieve_coder",
      "avoid_locks"
    ],
    "justification": "These functions interact with _ethBal and the respective balances, and can be called during reentrancy."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "retrieve_president",
      "retrieve_marketing",
      "retrieve_development",
      "retrieve_coder",
      "avoid_locks"
    ],
    "nesting_bound": {
      "retrieve_president": 1
    }
  },
  "phases": {
    "function": "retrieve_president",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "exit"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in transit during callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "president_balance + marketing_balance + development_balance + coder_balance <= _ethBal + inFlight",
    "stable_formula": "president_balance + marketing_balance + development_balance + coder_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "president_balance + marketing_balance + development_balance + coder_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of balances does not exceed the ETH balance plus any in-flight ETH during reentrancy."
  }
}
